/* UI-only current-run validation; it never changes routing or search definitions. */
(()=>{
const $=id=>document.getElementById(id),by=$,n=id=>Number($(id)?.value),freeIds=['freeTailwater','freeBackwater','freeSubmergence','freeOperation'];let dirty=true,current=null;
function resultText(){return [by('designScreening')?.textContent,by('optout')?.textContent].filter(Boolean).join(' ');}
const freeN=()=>freeIds.filter(id=>$(id)?.checked).length,freeOK=()=>Boolean($('freeDischarge')?.checked)&&freeN()===4,fmt=(v,d,u)=>Number.isFinite(v)?v.toFixed(d)+(u?' '+u:''):'尚未取得';
function root(){let e=$('diagnosticGuide');if(e)return e;e=document.createElement('section');e.id='diagnosticGuide';e.className='module-card diagnostic-guide';e.innerHTML='<h2>結果驗證｜三步判讀</h2><div class="three-step"></div><div class="diagnostic-list"></div><p class="diagnostic-scope"></p>';($('mod-evaluation')||$('status')?.parentElement)?.appendChild(e);const s=document.createElement('style');s.textContent='.diagnostic-guide{margin-top:16px;border:1px solid #bfd1dc;border-radius:8px;padding:15px;background:#fff}.three-step,.diagnostic-list{display:grid;gap:10px}.step-card,.diagnostic-item{border-left:5px solid #64748b;background:#f8fafc;padding:11px}.step-card h3{margin:0 0 7px;font-size:17px}.check-list{display:grid;gap:7px}.check-row{display:grid;grid-template-columns:82px 1fr;gap:8px;align-items:start}.badge{display:inline-block;border-radius:999px;padding:2px 8px;font-weight:700;font-size:13px;text-align:center;background:#e2e8f0}.badge.pass{background:#dcfce7;color:#166534}.badge.warn{background:#fef3c7;color:#92400e}.badge.stop{background:#ffe4e6;color:#be123c}.diagnostic-item{border-color:#e79a17;background:#fff8e7}.diagnostic-item.stop{border-color:#e11d48;background:#fff1f2}.diagnostic-item strong,.basis{display:block}.basis{font-size:13px;color:#526a78;margin-top:5px}.diagnostic-guide button{margin-top:7px;border:1px solid #0b557d;border-radius:4px;background:#fff;color:#0b557d;padding:6px 9px;font-weight:700;cursor:pointer}.diagnostic-scope{font-size:13px;color:#526a78;margin:12px 0 0}.diagnostic-focus{outline:3px solid #e79a17!important;outline-offset:2px;background:#fff8e7!important}';document.head.appendChild(s);return e;}
function tableBad(){if($('storageMode')?.value!=='table')return false;const r=($('storageTable')?.value||'').trim().split(/\n+/).map(x=>x.trim().split(/[ ,;\t]+/).map(Number));return r.length<2||r.some((x,i)=>x.length<2||x.some(v=>!Number.isFinite(v))||(i&&(x[0]<=r[i-1][0]||x[1]<=r[i-1][1])));}
function state(){if(current?.kind==='no-feasible')return '無可行解';if(dirty||!current)return '尚未執行';return '連續最佳化完成';}
function dominantLimits(){const a=[];for(const x of current?.limits||[]){if(/outflow|出流/i.test(x))a.push(['出流尖峰限制','outletSize']);else if(/water|水位/i.test(x))a.push(['最高水位限制','waterLimit']);else if(/drain|排空|殘留/i.test(x))a.push(['排空殘留限制','drainLimit']);else if(/storage|蓄水|boundary/i.test(x))a.push(['S(H) 邊界','storage']);}return a.length?a:[['已宣告的路由條件','routing']];}
function rows(){const a=[],x=current,h0=n('h0'),ha=n('hallow'),qa=n('qallow'),pre=dirty||!x||x.kind!=='feasible',add=(status,label,detail,target,reason)=>a.push({status,label,detail,target,reason});
 if(!(Number.isFinite(ha)&&ha>=h0))add('阻擋','最高水位 Hmax ≤ Hallow','Hallow = '+fmt(ha,3,'m')+'；必須不低於 H0 = '+fmt(h0,3,'m')+'。','water','Hallow 與初始水位基準不相容。');else if(pre)add('注意','最高水位 Hmax ≤ Hallow','尚未執行；Hallow = '+fmt(ha,3,'m')+'。','water','尚無本輪 Hmax。');else add(x.e.hp.h<=ha+1e-9?'通過':'阻擋','最高水位 Hmax ≤ Hallow','Hmax = '+fmt(x.e.hp.h,3,'m')+'；Hallow = '+fmt(ha,3,'m')+'。','water',x.e.hp.h<=ha+1e-9?'本輪 RK4 路由結果符合宣告限值。':'本輪 RK4 路由水位超過宣告限值。');
 if(!(qa>0))add('阻擋','最大出流 Qmax ≤ Qallow','Qallow = '+fmt(qa,4,'m³/s')+'；必須大於 0。','outflow','容許出流量未有效宣告。');else if(pre)add('注意','最大出流 Qmax ≤ Qallow','尚未執行；Qallow = '+fmt(qa,4,'m³/s')+'。','outflow','尚無本輪 Qmax。');else add(x.e.pout.qo<=qa+1e-9?'通過':'阻擋','最大出流 Qmax ≤ Qallow','Qmax = '+fmt(x.e.pout.qo,4,'m³/s')+'；Qallow = '+fmt(qa,4,'m³/s')+'。','outflow',x.e.pout.qo<=qa+1e-9?'本輪 RK4 路由結果符合宣告限值。':'本輪 RK4 路由出流超過宣告限值。');
 if(tableBad()||x?.r?.stateExceeded)add('阻擋','S(H) 邊界','已超出或無法確認宣告的蓄水量—水位邊界。','storage','路由不得外插 S(H) 曲線。');else if(pre)add('注意','排空殘留與 S(H) 邊界','尚未執行，排空殘留與邊界尚未完成檢核。','drain','尚無本輪完整路由紀錄。');else if(x.remain===null)add('阻擋','排空殘留與 S(H) 邊界','Te + Td 排空殘留不予評估；路由未完整到達宣告時點。','drain','無完整排空結果不可作設計判讀。');else {const l=n('residualPct');add(x.remain<=l+1e-9?'通過':'阻擋','排空殘留與 S(H) 邊界','殘留 = '+fmt(x.remain,2,'%')+'；宣告限制 = '+fmt(l,2,'%')+'；S(H) 邊界未超出。','drain',x.remain<=l+1e-9?'本輪結果符合已宣告排空條件。':'本輪結果未符合已宣告排空條件。');}
 if(freeOK())add(current?.kind==='no-feasible'?'注意':'通過','自由出流四項佐證','已完成 4/4 項使用者佐證。','free','僅表示使用者已宣告佐證完整。');else add('阻擋','自由出流四項佐證','已完成 '+freeN()+'/4 項；受限篩選與連續最佳化不可據此視為完成。','free','缺少尾水、回水／管摩阻、淹沒或操作控制佐證。');return a;}
function go(key){const m={storage:['mod-storage','storageTable'],water:['mod-optimization','hallow'],waterLimit:['mod-optimization','hallow'],outflow:['mod-optimization','qallow'],outletSize:['mod-outlet',$('weirOn')?.checked?'bw':'ao'],free:['mod-outlet','freeDischarge'],drain:['mod-optimization','residualPct'],drainLimit:['mod-optimization','residualPct'],routing:['mod-routing','run']}[key]||[],id=m[1];window.DSSWorkspacePages?.openTarget(m[0]);setTimeout(()=>{const e=$(id);if(e){e.classList.add('diagnostic-focus');e.focus({preventScroll:true});e.scrollIntoView({behavior:'smooth',block:'center'});}},40);}
function render(){const e=root(),s=state(),r=rows(),problems=r.filter(x=>x.status!=='通過'),badge=x=>'<span class="badge '+(x==='通過'?'pass':x==='阻擋'?'stop':'warn')+'">'+x+'</span>';let next='目前結果符合已宣告條件；仍須完成最終工程設計驗證。',buttons=[];
 if(s==='尚未執行')next='請先執行路由；未執行時不得判定任何條件為通過。';if(s==='無可行解'){const d=dominantLimits();next='阻擋：在目前宣告範圍內無可行解。主導限制：'+d.map(x=>x[0]).join('、')+'。請依工程依據調整對應變數，或補足 S(H) 資料；不得任意放寬 Qallow 或 Hallow。';buttons=d;}else if(problems.length){const p=problems.find(x=>x.status==='阻擋')||problems[0];next=p.status+'：'+p.label+'；'+p.reason;buttons=[[p.label,p.target]];}
 e.querySelector('.three-step').innerHTML='<div class="step-card"><h3>步驟 1｜計算狀態</h3>'+badge(s==='無可行解'?'阻擋':s==='尚未執行'?'注意':'通過')+' '+s+'</div><div class="step-card"><h3>步驟 2｜條件檢核</h3><div class="check-list">'+r.map(x=>'<div class="check-row">'+badge(x.status)+'<div><strong>'+x.label+'</strong><br>'+x.detail+'</div></div>').join('')+'</div></div><div class="step-card"><h3>步驟 3｜下一步</h3><strong>'+next+'</strong>'+(buttons.length?'<div>'+buttons.map(x=>'<button data-fix="'+x[1]+'">前往修正：'+x[0]+'</button>').join(' ')+'</div>':'')+'</div>';
 const cards=(s==='無可行解'?dominantLimits().map(x=>({status:'阻擋',label:'無可行解｜主導限制：'+x[0],detail:'本輪候選重跑未能同時符合已宣告條件。',target:x[1]})):problems).filter(x=>x.status!=='注意'||s!=='尚未執行');e.querySelector('.diagnostic-list').innerHTML=cards.map(x=>'<div class="diagnostic-item '+(x.status==='阻擋'?'stop':'')+'"><strong>'+x.status+'｜'+x.label+'</strong><span>'+x.detail+'</span><button data-fix="'+x.target+'">前往修正</button></div>').join('');e.querySelector('.diagnostic-scope').textContent='本區僅呈現本輪計算與使用者已宣告條件；不改變任何數值、可行性判定、Pareto 排序或工程責任界線。';e.querySelectorAll('button[data-fix]').forEach(b=>b.onclick=()=>go(b.dataset.fix));}
window.DSSDiagnostics=Object.freeze({render,go});['run','optimize','continuousGlobal'].forEach(id=>$(id)?.addEventListener('click',()=>{dirty=true;current=null;render();}));window.addEventListener('dss:continuous-result',e=>{current=e.detail;dirty=false;render();});document.addEventListener('input',e=>{if(!e.target.closest('#diagnosticGuide')){dirty=true;current=null;setTimeout(render,0);}},true);document.addEventListener('change',e=>{if(!e.target.closest('#diagnosticGuide')){dirty=true;current=null;setTimeout(render,0);}},true);function watchResultBoxes(){const boxes=['designScreening','optout','crossOut'].map(by).filter(Boolean);boxes.forEach(x=>new MutationObserver(render).observe(x,{subtree:true,childList:true,characterData:true}));}watchResultBoxes();setTimeout(render,160);
})();
